'use strict';

function plainText(value) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };
  return String(value || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?[a-z][a-z0-9]*(?:\s[^>]*)?>/gi, ' ')
    .replace(/&#(x[0-9a-f]+|[0-9]+);?/gi, function (_, code) {
      const number = code.charAt(0).toLowerCase() === 'x' ?
        parseInt(code.slice(1), 16) : parseInt(code, 10);
      if (!Number.isFinite(number) || number < 0 || number > 0x10ffff) return '';
      try { return String.fromCodePoint(number); } catch (_) { return ''; }
    })
    .replace(/&([a-z]+);/gi, function (match, name) {
      return Object.prototype.hasOwnProperty.call(named, name.toLowerCase()) ?
        named[name.toLowerCase()] : match;
    })
    .replace(/[\t\r\n ]+/g, ' ')
    .replace(/([“‘（【《〈])\s+/g, '$1')
    .replace(/\s+([”’）】》〉，。！？；：、])/g, '$1')
    .trim();
}

function normalizeTerm(value) {
  const selected = String(value || '').trim();
  const match = selected.match(/[A-Za-z][A-Za-z'’ -]{0,79}/);
  return match ? match[0].replace(/’/g, "'").trim() : '';
}

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function firstWord(data) {
  const ecWords = data && data.ec && asArray(data.ec.word);
  if (ecWords && ecWords.length > 0) return ecWords[0] || {};
  const simpleWords = data && data.simple && asArray(data.simple.word);
  return simpleWords && simpleWords.length > 0 ? simpleWords[0] || {} : {};
}

function collectTranslations(word) {
  const output = [];
  asArray(word && word.trs).forEach(function (translationGroup) {
    asArray(translationGroup && translationGroup.tr).forEach(function (translation) {
      const items = translation && translation.l && translation.l.i;
      const values = Array.isArray(items) ? items : (items ? [items] : []);
      values.forEach(function (item) {
        const text = plainText(item).slice(0, 12000);
        if (text && output.indexOf(text) < 0 && output.length < 12) output.push(text);
      });
    });
  });
  return output;
}

function collectForms(word) {
  const output = [];
  asArray(word && word.wfs).forEach(function (entry) {
    const form = entry && entry.wf;
    const name = plainText(form && form.name);
    const value = plainText(form && form.value);
    if (name && value && output.length < 12) output.push(name + '：' + value);
  });
  return output;
}

module.exports.dictionary = async function (input) {
  const value = input || {};
  const term = normalizeTerm(value.word || value.context);
  if (!term) {
    return { title: '有道英译中词典', text: '请选择要查询的英文单词或短语。' };
  }

  try {
    const response = await Promise.resolve(reader.http.fetch({
      url: 'https://dict.youdao.com/jsonapi?q=' + encodeURIComponent(term),
      method: 'GET',
      headers: {
        'Accept': 'application/json,text/plain,*/*',
        'Referer': 'https://dict.youdao.com/',
        'User-Agent': 'Mozilla/5.0 FishReaderDictionary/1.0'
      },
      timeoutMs: 15000
    }));
    const status = Number(response && response.status || 0);
    const body = String(response && response.body || '');
    if (status < 200 || status >= 400 || !body) {
      return { title: term + ' · 有道英译中词典', text: '查询失败：HTTP ' + status + '。' };
    }

    let data;
    try { data = JSON.parse(body); } catch (_) {
      return { title: term + ' · 有道英译中词典', text: '查询失败：返回内容不是有效的词典数据。' };
    }
    const word = firstWord(data);
    const translations = collectTranslations(word);
    if (translations.length === 0) {
      return { title: term + ' · 有道英译中词典', text: '暂未收录该英文单词或短语。' };
    }

    const lines = [];
    const ukPhone = plainText(word.ukphone);
    const usPhone = plainText(word.usphone);
    const phones = [];
    if (ukPhone) phones.push('英 /' + ukPhone + '/');
    if (usPhone && usPhone !== ukPhone) phones.push('美 /' + usPhone + '/');
    if (phones.length > 0) lines.push(phones.join('　'));
    if (lines.length > 0) lines.push('');
    translations.forEach(function (translation, index) {
      lines.push(String(index + 1) + '. ' + translation);
    });
    const forms = collectForms(word);
    if (forms.length > 0) lines.push('', '词形：' + forms.join('；'));
    lines.push('', '数据：有道词典（在线查询）');
    return { title: term + ' · 有道英译中词典', text: lines.join('\n') };
  } catch (error) {
    const message = (error && error.message ? String(error.message) :
      String(error || '未知错误')).slice(0, 500);
    return { title: term + ' · 有道英译中词典', text: '查询失败：' + message };
  }
};
